      type: 'object',
      properties: {
        customer_id: {
          type: 'string',
          description: 'The customer ID to look up'
        }
      },
      required: ['customer_id']
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    throw new Error(`Tool not found: ${name}`);
  }

  if (!args || typeof args.customer_id !== 'string' || !args.customer_id) {
    throw new Error('Missing required parameter: customer_id');
  }

  const customer = customers[args.customer_id];
  if (!customer) {
    throw new Error(`Customer not found: ${args.customer_id}`);
  }

  return {
    content: [{
      type: 'text',
      text: `${customer.name} (${customer.tier})`
    }]
  };
}
